// test/og.test.js
// The site standard: every page has an Open Graph card. Routes point og:image
// at /img/og/<slug>.png, so a page without a card unfurls blank when shared.
// This guards both directions: no page missing a card, no orphan card left
// behind. Cards are generated by scripts/og/render.sh.
import site from '../site.config.js'
import { describe, it, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

import { decodePng } from '../scripts/icon/png.mjs'
import { readRamps } from '../src/lib/kit-parts.js'
import { build } from '../src/server.js'
import { loadFeedEntries } from '../src/routes/feed.js'
import { pathFor } from '../src/lib/entry-kind.js'
import { FIXTURES } from './fixtures.js'

const OG_DIR = join(import.meta.dirname, '../src/static/img/og')
// Static pages that carry their own og:image (set in each route's meta).
// default.png also backs the home page and the error pages, which set none.
// the fanned stack is a page too (BIBLE.md section 5), and so is each document
const INDEX_CARDS = ['default', 'work', 'case-studies', 'about', 'feed', 'credits']

describe('OG cards: one per page (the site standard)', () => {
  it('every static page and content entry has an og card on disk', async () => {
    const entries = await loadFeedEntries()
    // External entries have no local page to unfurl; their host owns the card.
    const required = new Set([
      ...INDEX_CARDS,
      ...entries.filter((e) => !e.hidden && !e.externalUrl).map((e) => e.slug),
    ])
    for (const slug of required) {
      assert.ok(
        existsSync(join(OG_DIR, `${slug}.png`)),
        `missing og card src/static/img/og/${slug}.png — every page needs one (add it to scripts/og/render.sh)`
      )
    }
  })

  it('has no orphan og cards (every card maps to a page or entry)', async () => {
    const entries = await loadFeedEntries()
    // A card for an external entry IS an orphan: no local page ever serves it.
    const known = new Set([...INDEX_CARDS, ...entries.map((e) => e.slug)])
    const orphans = readdirSync(OG_DIR)
      .filter((f) => f.endsWith('.png'))
      .map((f) => f.replace(/\.png$/, ''))
      .filter((slug) => !known.has(slug))
    assert.deepEqual(orphans, [], `orphan og cards with no page/entry: ${orphans.join(', ')}`)
  })
})

// A card is the site's material at billboard size (scripts/og/render.sh):
// every px one of the grey ramp's tokens, the type drawn unsmoothed at whole
// dots. A card resaved through a resampler, rendered at 2x and scaled down,
// or left behind when a grey token was retuned is a card of grey soup, and
// this is where it shows.
describe('OG cards: on the ramp', () => {
  // mutation: og.card-off-ramp
  it('every px of every card is a grey token', () => {
    const greys = new Set(readRamps().grey)
    const cards = readdirSync(OG_DIR).filter((f) => f.endsWith('.png'))
    assert.ok(cards.length >= INDEX_CARDS.length, `only ${cards.length} cards found`)
    for (const f of cards) {
      const { rgba } = decodePng(readFileSync(join(OG_DIR, f)))
      const off = new Map()
      for (let i = 0; i < rgba.length; i += 4) {
        const h = '#' + [0, 1, 2].map((k) => rgba[i + k].toString(16).padStart(2, '0')).join('')
        if (!greys.has(h) || rgba[i + 3] !== 255) off.set(h, (off.get(h) || 0) + 1)
      }
      assert.equal(
        off.size,
        0,
        `${f} is off the ramp: ${[...off]
          .slice(0, 6)
          .map(([h, n]) => `${h} x${n}`)
          .join(', ')}` + ' (rerun bash scripts/og/render.sh)'
      )
    }
  })
})

// The card-on-disk check above pins the files; this pins the pointer. A route
// can declare an og:image that unfurls blank because the URL is a typo or an
// unrendered card. Render each canvas-served route's head and follow its
// og:image back to a real file. External entries 302 (no head), so they are
// not in the list.
describe('OG pointer: every route og:image resolves to a file on disk', () => {
  let app
  before(async () => {
    app = await build({ logger: false })
  })
  after(async () => {
    await app.close()
  })

  // mutation: og.work-card-typo
  it('each canvas route points og:image at a card that exists', async () => {
    const entries = await loadFeedEntries()
    const local = entries.filter((e) => !e.hidden && !e.externalUrl)
    const routes = [
      '/',
      '/work',
      '/case-studies',
      '/feed',
      '/about',
      '/credits',
      ...local.map(pathFor),
    ]
    // Sanity: the representative content routes are actually in the swept set,
    // and the external ones (no local head to unfurl) are not.
    assert.ok(routes.includes(`/work/${FIXTURES.caseStudy}`), 'a case study is swept')
    assert.ok(routes.includes(`/${FIXTURES.experiment}`), 'an experiment is swept')
    assert.ok(!routes.includes(`/feed/${FIXTURES.external}`), 'external entries have no local card')
    for (const url of routes) {
      const r = await app.inject({ method: 'GET', url })
      assert.equal(r.statusCode, 200, `${url} should render a page`)
      const og = r.body.match(/<meta property="og:image" content="([^"]+)"/)
      assert.ok(og, `${url} declares an og:image`)
      const file = og[1].startsWith(`${site.url}/img/og/`)
        ? /\/img\/og\/(.+\.png)\?v=[0-9a-f]{8}$/.exec(og[1])
        : null
      assert.ok(file, `${url} og:image should point under /img/og (got ${og[1]})`)
      assert.ok(
        existsSync(join(OG_DIR, file[1])),
        `${url} og:image ${og[1]} has no file at src/static/img/og/${file[1]}`
      )
    }
  })
})
